## Inputs

```
export type RadioGroupComponentInputs = {
  /**
   * Brand Area → accent-color der Radios.
   *
   * @default co
   */
  area?: CdsArea;
  /**
   * Deaktiviert; auch über Angular-Forms (setDisabledState) steuerbar.
   *
   * @default false
   */
  disabled?: boolean; // two-way: [(disabled)]
  /**
   * Gruppen-Label (die Frage) → <legend>.
   *
   * @default Optionen
   */
  legend?: string;
  /** Gemeinsamer name aller Radios der Gruppe. Default eindeutig. */
  name?: string;
  /**
   * Auswahloptionen (Label = Wert).
   *
   * @default []
   */
  options?: string[];
  /**
   * Pflichtauswahl → required + .req-Asterisk.
   *
   * @default false
   */
  required?: boolean;
  /**
   * Aktuell gewählter Wert. Two-Way (`[(value)]`) UND Angular-Forms.
   *
   * @default ''
   */
  value?: string; // two-way: [(value)]
}
```

## Outputs

```
export type RadioGroupComponentOutputs = {
  /** Deaktiviert; auch über Angular-Forms (setDisabledState) steuerbar. */
  disabledChange: (e: boolean) => void;
  /** Aktuell gewählter Wert. Two-Way (`[(value)]`) UND Angular-Forms. */
  valueChange: (e: string) => void;
}
```
